"""One-time, idempotent cleanup for LittleNet pending repository items 1-3.

This script is intentionally conservative: every security-sensitive source edit
checks the exact old source marker before replacing it, and a second run is a
no-op for already-patched blocks. It never reads or writes runtime secrets.
"""
from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[1]


def read(rel):
    return (ROOT / rel).read_text(encoding="utf-8")


def write(rel, text):
    (ROOT / rel).write_text(text, encoding="utf-8")


def replace_once(text, old, new, label):
    if new in text:
        return text
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{label}: expected exactly one old block, found {count}")
    return text.replace(old, new, 1)


def replace_between(text, start, end, replacement, label):
    if replacement in text:
        return text
    i = text.find(start)
    if i < 0:
        raise RuntimeError(f"{label}: start marker not found")
    j = text.find(end, i)
    if j < 0:
        raise RuntimeError(f"{label}: end marker not found")
    return text[:i] + replacement + text[j:]


# 1. Guardian verification: close demo/mock and token-only fail-open paths.
service = read("auth/service.py")
service = replace_once(service, '    doc_type = form_data.get("document_type", "AADHAAR_MOCK")\n', '    doc_type = form_data.get("document_type", "GUARDIAN_DECLARATION")\n', "guardian document default")
service = replace_once(service, '''    is_express = (\n        form_data.get("verification_mode") == "EXPRESS"\n        or form_data.get("express_verify") == "1"\n        or (not selfie_bytes and not doc_number and consent)\n    )\n''', '''    is_express = (\n        form_data.get("verification_mode") == "EXPRESS"\n        or form_data.get("express_verify") == "1"\n    )\n''', "explicit express selection")
service = replace_once(service, '''        if dob:\n            try:\n                birth_year = int(dob.split("-")[0])\n                if birth_year > 2006:\n                    return {"success": False, "error": "Adult verification failed: Parent must be 18 years of age or older."}\n            except (ValueError, IndexError):\n                pass\n''', '''        if dob:\n            try:\n                birth_date = datetime.strptime(dob, "%Y-%m-%d").date()\n                today = datetime.now(timezone.utc).date()\n                declared_age = today.year - birth_date.year - (\n                    (today.month, today.day) < (birth_date.month, birth_date.day)\n                )\n                if declared_age < 18:\n                    return {"success": False, "error": "Adult verification failed: Parent must be 18 years of age or older."}\n            except ValueError:\n                return {"success": False, "error": "Please provide a valid date of birth for the parent or guardian."}\n''', "current-date adult age calculation")
service = replace_once(service, '''            adult_res = verify_adult_face(tmp_path)\n            if not adult_res.get('is_adult', True):\n                return {"success": False, "error": "Adult verification failed: The live camera face was detected as a minor. A parent or legal adult guardian must complete this verification."}\n''', '''            adult_res = verify_adult_face(tmp_path)\n            if not isinstance(adult_res, dict) or adult_res.get('is_adult') is not True:\n                return {"success": False, "error": "Adult verification failed: a verified adult parent or legal guardian must complete this live-camera check."}\n''', "adult face fail closed")
service = replace_once(service, '''    else:\n        # 1. Verify Identity Document\n        id_res = default_verification_provider.verify_parent_identity(\n''', '''    else:\n        # The deterministic Aadhaar mock is development-only. A crafted POST\n        # must never be able to select it on a public deployment.\n        base_url = str(getattr(Config, "BASE_URL", "") or "").lower()\n        allow_mock_identity = (\n            os.getenv("LITTLENET_ALLOW_MOCK_IDENTITY", "").strip().lower() in {"1", "true", "yes"}\n            and ("localhost" in base_url or "127.0.0.1" in base_url)\n            and not base_url.startswith("https://")\n        )\n        if not allow_mock_identity:\n            return {\n                "success": False,\n                "error": "Legacy demo identity verification is disabled. Use Express Guardian Verification with the live camera.",\n                "status": "DISABLED",\n            }\n\n        # Local-development-only mock identity path.\n        id_res = default_verification_provider.verify_parent_identity(\n''', "public mock identity gate")
service = replace_once(service, '''        ver_row = cur.fetchone()\n        verification_data = {\n            "status": ver_row["verification_status"] if ver_row else "VERIFIED",\n            "masked_id": ver_row["masked_id"] if ver_row and ver_row.get("masked_id") else "XXXX-XXXX-5678",\n            "document_type": ver_row["document_type"] if ver_row and ver_row.get("document_type") else "AADHAAR_MOCK"\n        }\n\n        return {\n''', '''        ver_row = cur.fetchone()\n        if not ver_row or ver_row.get("verification_status") != "VERIFIED":\n            return {"valid": False, "reason": "PARENT_VERIFICATION_REQUIRED", "data": data}\n        verification_data = {\n            "status": "VERIFIED",\n            "masked_id": ver_row["masked_id"] if ver_row.get("masked_id") else "GUARDIAN-VERIFIED",\n            "document_type": ver_row["document_type"] if ver_row.get("document_type") else "GUARDIAN_DECLARATION"\n        }\n\n        return {\n''', "approval details require verification record")
service = replace_between(service, "def approve_child_account(token):", "def login_user(identifier, password):", '''def approve_child_account(token):\n    """Deprecated token-only approval path; intentionally fail closed.\n\n    Child activation requires a verified Parent session and the normal\n    ``process_child_decision`` authorization path.\n    """\n    raise RuntimeError("Direct token-only child approval is disabled; parent verification is required")\n\n''', "disable token-only approval helper")
write("auth/service.py", service)

routes = read("auth/routes.py")
routes = replace_once(routes, "verification=check.get('verification', {'status': 'VERIFIED', 'masked_id': 'XXXX-XXXX-5678'}), token=token", "verification=check.get('verification', {'status': 'UNVERIFIED', 'masked_id': 'GUARDIAN-UNVERIFIED'}), token=token", "approval template fallback")
routes = replace_between(routes, "@auth_bp.route('/approve/<token>/',methods=['GET','POST'])", "@auth_bp.route('/register-parent', methods=['GET', 'POST'])", '''@auth_bp.route('/approve/<token>/', methods=['GET', 'POST'])\n@limiter.limit('30 per minute')\ndef approve_child(token):\n    """Legacy link compatibility without token-only activation.\n\n    Old invitations are routed into the verified parent flow. A leaked or\n    replayed UUID can no longer activate a child account by itself.\n    """\n    return redirect(f'/verify-parent/{token}/', code=303)\n\n\n''', "legacy approve route")
write("auth/routes.py", routes)

